"""A parameterised retry decorator."""
import functools


def retry(attempts=3, exceptions=(Exception,), on_retry=None):
    def decorator(func):
        @functools.wraps(func)   # copies __name__/__doc__ and sets __wrapped__
        def wrapper(*args, **kwargs):
            last_exc = None
            for attempt in range(1, attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last_exc = exc
                    if attempt < attempts and on_retry is not None:
                        on_retry(exc, attempt)
            raise last_exc
        return wrapper
    return decorator

