import pytest

from retry import retry


def test_succeeds_after_transient_failures():
    calls = {"n": 0}

    @retry(attempts=3, exceptions=(ConnectionError,))
    def flaky():
        calls["n"] += 1
        if calls["n"] < 3:
            raise ConnectionError("transient")
        return "ok"

    assert flaky() == "ok"
    assert calls["n"] == 3


def test_gives_up_and_raises_last_exception():
    @retry(attempts=2, exceptions=(ValueError,))
    def always():
        raise ValueError("nope")

    with pytest.raises(ValueError, match="nope"):
        always()


def test_no_retry_on_success():
    calls = {"n": 0}

    @retry(attempts=5)
    def good():
        calls["n"] += 1
        return 42

    assert good() == 42
    assert calls["n"] == 1

import pytest

from retry import retry


def test_unlisted_exception_is_not_retried():
    calls = {"n": 0}

    @retry(attempts=3, exceptions=(ConnectionError,))
    def boom():
        calls["n"] += 1
        raise KeyError("unlisted")

    with pytest.raises(KeyError):
        boom()
    assert calls["n"] == 1, "unlisted exceptions must not be retried"


def test_args_and_kwargs_pass_through():
    @retry(attempts=2)
    def add(a, b, *, c=0):
        return a + b + c

    assert add(1, 2, c=3) == 6

from retry import retry


def test_on_retry_called_between_attempts():
    seen = []

    @retry(attempts=3, exceptions=(RuntimeError,), on_retry=lambda exc, n: seen.append(n))
    def always():
        raise RuntimeError("x")

    try:
        always()
    except RuntimeError:
        pass
    # 3 attempts -> callback fires after attempt 1 and 2, not after the last
    assert seen == [1, 2]


def test_on_retry_not_called_on_success():
    seen = []

    @retry(attempts=3, on_retry=lambda exc, n: seen.append(n))
    def good():
        return 1

    good()
    assert seen == []

from retry import retry


@retry(attempts=2)
def documented(x):
    """Return x unchanged."""
    return x


def test_name_preserved():
    assert documented.__name__ == "documented", "use functools.wraps"


def test_docstring_preserved():
    assert documented.__doc__ == "Return x unchanged."


def test_wrapped_attribute_present():
    assert hasattr(documented, "__wrapped__"), "functools.wraps sets __wrapped__"
    assert documented.__wrapped__(5) == 5

